import{_ as s,l as n,o as r,c as i,v as e,p as l,x as t,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"Armstrong 公理","description":"","frontmatter":{"title":"Armstrong 公理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/armstrong-axioms.md","filePath":"cs/armstrong-axioms.md","lastUpdated":1789023840000}'),A={name:"cs/armstrong-axioms.md"};function E(h,a,c,F,_,B){const o=n("Mermaid");return r(),i("div",null,[a[1]||(a[1]=e('<h1 id="armstrong-公理" tabindex="-1">Armstrong 公理 <a class="header-anchor" href="#armstrong-公理" aria-label="Permalink to &quot;Armstrong 公理&quot;">​</a></h1><div class="epigraph"><p>函数依赖的语法推导由自反、增广、传递三条公理完备：能推出的，恰是所有实例上都成立的。</p><footer>—— 据 Armstrong, Dependency Structures of Data Base Relationships, IFIP 1974；Beeri, Fagin and Howard；Ramakrishnan and Gehrke</footer></div><p>查询语言进阶在<a href="/cs/prepared-plan-cache">计划缓存</a>收口。本课打开依赖理论：主干 <a href="/cs/normal-forms">范式</a> 已经用函数依赖（FD）判断宽表，但把「F 蕴含 X→Y」当成能看出来的事实。缺口是<strong>证明系统</strong>：Armstrong 公理给出可靠完备的推导，闭包算法下一课才当决策过程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FD \\(X \\to Y\\) 表示：任何合法实例上，X 值相同则 Y 值相同。一组 FD \\(F\\) 的逻辑蕴含 \\(F \\models X \\to Y\\)：每个满足 \\(F\\) 的关系也满足 \\(X \\to Y\\)。人眼列举无穷实例不可能。缺口是语法：\\(F \\vdash X \\to Y\\) 当且仅当语义蕴含（完备性），且推不出假依赖（可靠性）。</p><p>Armstrong：自反（若 \\(Y \\subseteq X\\) 则 \\(X \\to Y\\)）；增广（\\(X \\to Y\\) 则 \\(XZ \\to YZ\\)）；传递（\\(X \\to Y\\) 且 \\(Y \\to Z\\) 则 \\(X \\to Z\\)）。由此可导出合并、分解、伪传递等规则，便于手推，不是另一套公理。</p><p><span class="marginnote">Armstrong 1974。Beeri, Fagin, Howard 证明该公理系统对 FD 完备。多值依赖需要更多公理，那是 4NF 课。本课只处理 FD。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>要从 \\(F\\) 证明 \\(X \\to Y\\)，用公理做有限步推导，或（实践上）算 \\(X\\) 在 \\(F\\) 下的闭包 \\(X^+\\)，看 \\(Y \\subseteq X^+\\)——算法正确性依赖本课的完备性。本课先钉公理，下一课才写闭包与最小覆盖。</p><p>例子：已知 \\(A \\to B\\)，\\(B \\to C\\)，由传递得 \\(A \\to C\\)；再增广得 \\(AD \\to CD\\)。自反给出平凡依赖，避免「空集决定一切」的误读：空集决定的是空属性集，不是全部属性。</p>',10)),(r(),l(p,null,{default:t(()=>[m(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22FD%20%E9%9B%86%20F%22%5D%20--%3E%20AX%5B%22Armstrong%20%E6%8E%A8%E5%AF%BC%22%5D%0A%20%20AX%20--%3E%20SYN%5B%22F%20%E6%8E%A8%E5%87%BA%20X%20%E5%86%B3%E5%AE%9A%20Y%22%5D%0A%20%20INST%5B%22%E6%BB%A1%E8%B6%B3%20F%20%E7%9A%84%E5%AE%9E%E4%BE%8B%22%5D%20--%3E%20SEM%5B%22F%20%E8%95%B4%E5%90%AB%20X%20%E5%86%B3%E5%AE%9A%20Y%22%5D%0A%20%20SYN%20--%3E%20EQ%5B%22%E5%8F%AF%E9%9D%A0%E5%AE%8C%E5%A4%87%E5%88%99%E9%87%8D%E5%90%88%22%5D%0A%20%20SEM%20--%3E%20EQ%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>范式分解「沿违反的 FD 切开」默认我们能列出隐含依赖。缺完备性会漏拆；缺可靠性会拆错。键的定义「决定全部属性」同样是闭包等于 \\(U\\)，建立在本课上。</p><p>包与 NULL：经典 FD 理论假定无 NULL、集合语义。SQL 表有 NULL 时「相等」变糊，工程约束用唯一索引近似 FD。本课理论按经典关系；与 <a href="/cs/sql-null">三值</a> 的缝点名即可。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把闭包线性时间算法写完，不定义正则覆盖。也不引入嵌入式依赖、元组生成依赖的一般表aux。3NF/BCNF 的判定下一课之后用闭包做。</p><p>后课默认：谈到 \\(F\\) 蕴含某 FD，指 Armstrong 可推（等价于所有实例上成立）。查询语言课的约束检查是运行时；这里是模式设计时的蕴涵。</p><p>公理是证明系统，不是 DBMS 里的一个模块名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自反、增广、传递对 FD 可靠完备。</li><li>语义蕴含与语法推导重合，键与范式才可计算。</li><li>闭包与最小覆盖下一课：把推导变成算法。</li><li>出处：Armstrong 1974；Beeri, Fagin and Howard；Ramakrishnan and Gehrke。</li></ul>',9))])}const g=s(A,[["render",E]]);export{D as __pageData,g as default};
